// do you love the color of the sky?
int[] text1 = int[](0x64, 0x6F, 0x20, 0x79, 0x6F, 0x75, 0x20, 0x6C, 0x6F, 0x76, 0x65, 0x20, 0x74, 0x68, 0x65, 0x20, 0x63, 0x6F, 0x6C, 0x6F, 0x72, 0x20, 0x6F, 0x66, 0x20, 0x74, 0x68, 0x65, 0x20, 0x73, 0x6B, 0x79, 0x3F, 0x20);
// which one?
int[] text2 = int[](0x77, 0x68, 0x69, 0x63, 0x68, 0x20, 0x6F, 0x6E, 0x65, 0x3F, 0x20);

// the sky colors
const vec3[] colors = vec3[](
    vec3(1.0, 1.0, 1.0),
    vec3(0.6, 0.8, 1.0),
    vec3(0.3, 0.5, 0.8),
    vec3(0.1, 0.3, 0.5),
    vec3(0.8, 0.7, 0.3),
    vec3(0.7, 0.3, 0.1),
    vec3(0.0, 0.0, 0.0),
    vec3(0.6, 0.4, 0.8),
    vec3(1.0, 0.5, 0.5)
);

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float time = (1.0 - fragCoord.y / iResolution.x) + iTime * 0.1 - 1.0;

    // slight dither to reduce color banding on low bit depth displays
    time += texture(iChannel1, mod(fragCoord / iChannelResolution[1].xy, iResolution.xy)).r * 0.2;

    // select color based on time var
    vec3 col = mix(
        colors[int(time) % colors.length()],
        colors[int(ceil(time)) % colors.length()],
        smoothstep(0.0, 1.0, fract(time))
    );

    // text scale
    float scale = iResolution.x / float(text1.length());

    // render only on the top
    if (iResolution.y - fragCoord.y <= scale) {
        int index = int(fragCoord.x / scale);

        // select character in correct string
        int char = time < 6.0 ? text1[index] : text2[index];
        if (char == 0x20) char = 0x30;

        // get char texture
        float letter = texture(iChannel0, (mod(vec2(fragCoord.x, fragCoord.y - iResolution.y) * 64.0 / scale, 64.0) + vec2(char % 16, (256 - char) / 16) * 64.0) / iChannelResolution[0].xy).x;

        // mix
        col = mix(col, vec3(0), letter);
    }

    // output
    fragColor = vec4(col,1.0);
}
